import { SetupGuideTranslation } from "../../../Components/SetupGuide/SetupGuideTranslation";

/*
 * The VMware setup guide in Hindi (#8341): each piece of the English
 * guide's markdown (Pages/VMware/Utils/DocumentationMarkdown.ts) and its
 * Hindi. Code, field names and product names are as the English writes
 * them, and what the Dashboard draws is named as its Hindi words it.
 * Change it with the English, in the same pull request
 * (SetupGuideDocumentationInLocale).
 */
const TRANSLATION: SetupGuideTranslation = {
  "Docker Engine 20.10+ with the Docker Compose v2 plugin, on a machine that can reach vCenter over HTTPS (TCP 443) — ideally not a VM on the cluster it watches":
    "Docker Engine 20.10+ और Docker Compose v2 प्लगइन, ऐसी मशीन पर जो HTTPS (TCP 443) पर vCenter तक पहुँच सके — बेहतर है कि वह उसी क्लस्टर की VM न हो जिस पर वह नज़र रखती है",
  "vCenter Server or ESXi **7.0 or later** (the collector's `vcenter` receiver supports vSphere 7 and 8)":
    "vCenter Server या ESXi **7.0 या नया** (कलेक्टर का `vcenter` रिसीवर vSphere 7 और 8 को सपोर्ट करता है)",
  "One agent per vCenter Server, or per standalone ESXi host that no vCenter manages":
    "हर vCenter Server के लिए एक एजेंट, या हर उस स्वतंत्र ESXi होस्ट के लिए एक, जिसे कोई vCenter नहीं संभालता",
  "1. Create the account: *Menu → Administration → Single Sign On → Users and Groups*, pick the `vsphere.local` domain (or your identity source), **Add** a user such as `oneuptime` and set a password. This yields the principal `oneuptime@vsphere.local`.":
    "1. खाता बनाएँ: *Menu → Administration → Single Sign On → Users and Groups*, `vsphere.local` डोमेन (या अपना पहचान स्रोत) चुनें, **Add** से `oneuptime` जैसा उपयोगकर्ता जोड़ें और पासवर्ड सेट करें। इससे प्रिंसिपल `oneuptime@vsphere.local` मिलता है।",
  "2. Grant the role: select the top-level **vCenter Server** object in the *Hosts and Clusters* inventory, open the **Permissions** tab, click **Add**, choose the user, set the role to **Read-Only**, and tick **Propagate to children**.":
    "2. भूमिका दें: *Hosts and Clusters* इन्वेंटरी में सबसे ऊपर का **vCenter Server** ऑब्जेक्ट चुनें, **Permissions** टैब खोलें, **Add** पर क्लिक करें, उपयोगकर्ता चुनें, भूमिका **Read-Only** रखें और **Propagate to children** पर टिक करें।",
  "Propagation is the part people miss. The receiver walks datacenters → clusters → hosts → VMs → datastores → resource pools, and every object the user cannot see is silently absent from the metrics — a Read-Only role granted on the vCenter object *without* propagation yields an inventory with nothing in it.":
    "प्रसार ही वह हिस्सा है जो लोग भूल जाते हैं। रिसीवर डेटा सेंटर → क्लस्टर → होस्ट → VM → डेटास्टोर → संसाधन पूल से होकर गुज़रता है, और हर वह ऑब्जेक्ट जिसे उपयोगकर्ता नहीं देख सकता, मेट्रिक से चुपचाप गायब रहता है — vCenter ऑब्जेक्ट पर प्रसार के *बिना* दी गई Read-Only भूमिका खाली इन्वेंटरी देती है।",
  "From a machine with administrator credentials:":
    "एडमिनिस्ट्रेटर क्रेडेंशियल वाली मशीन से:",
  "This creates `oneuptime@vsphere.local` with the Read-Only role on the vCenter root, propagated to every object below it.":
    "यह vCenter रूट पर Read-Only भूमिका के साथ `oneuptime@vsphere.local` बनाता है, जो उसके नीचे के हर ऑब्जेक्ट तक फैलती है।",
  "For an ESXi host that no vCenter manages, create the user under *Host → Manage → Security & Users → Users* in the ESXi Host Client, and assign it the Read-Only role under *Host → Manage → Security & Users → Permissions*.":
    "जिस ESXi होस्ट को कोई vCenter नहीं संभालता, उसके लिए ESXi Host Client में *Host → Manage → Security & Users → Users* के अंतर्गत उपयोगकर्ता बनाएँ, और *Host → Manage → Security & Users → Permissions* के अंतर्गत उसे Read-Only भूमिका दें।",
  "In the next step, use the host itself as the endpoint (`https://esxi01.example.com`) with this local user. Everything the host knows is collected — the host, its VMs, datastores and resource pools; a standalone host has no datacenter or cluster object, so those pages stay empty.":
    "अगले चरण में, इस स्थानीय उपयोगकर्ता के साथ होस्ट को ही एंडपॉइंट (`https://esxi01.example.com`) के रूप में इस्तेमाल करें। होस्ट जो कुछ जानता है वह सब इकट्ठा होता है — होस्ट, उसकी VM, डेटास्टोर और संसाधन पूल; स्वतंत्र होस्ट में कोई डेटा सेंटर या क्लस्टर ऑब्जेक्ट नहीं होता, इसलिए वे पेज खाली रहते हैं।",
  "The script asks for your OneUptime URL and ingestion key, both shown in step 1 (pick a key there to have them filled in here), and then for:":
    "स्क्रिप्ट आपका OneUptime URL और इंजेशन कुंजी पूछती है, दोनों चरण 1 में दिखते हैं (उन्हें यहाँ भरा पाने के लिए वहाँ एक कुंजी चुनें), और फिर ये पूछती है:",
  "- **vCenter name** — how the vCenter appears in OneUptime. Give every vCenter its own and keep it stable: a new name registers a new vCenter.":
    "- **vCenter का नाम**: OneUptime में vCenter किस नाम से दिखता है। हर vCenter को अपना नाम दें और उसे स्थिर रखें: नया नाम एक नया vCenter दर्ज करता है।",
  "- **vCenter endpoint** — scheme and host, without `/sdk`, e.g. `https://vcsa.example.com`.":
    "- **vCenter एंडपॉइंट**: स्कीम और होस्ट, `/sdk` के बिना, जैसे `https://vcsa.example.com`।",
  "- **The read-only user and its password** — the password is read without echo.":
    "- **केवल-पढ़ने वाला उपयोगकर्ता और उसका पासवर्ड**: पासवर्ड बिना दिखाए पढ़ा जाता है।",
  "- **TLS verification** — whether to skip it, since vCenter ships a self-signed certificate by default; and the **collection interval** (`2m`).":
    "- **TLS सत्यापन**: इसे छोड़ना है या नहीं, क्योंकि vCenter डिफ़ॉल्ट रूप से स्व-हस्ताक्षरित प्रमाणपत्र के साथ आता है; और **संग्रह अंतराल** (`2m`)।",
  "- **OneUptime AI agent** — whether it may apply fixes; answer **N** to keep it read-only.":
    "- **OneUptime AI एजेंट**: क्या यह सुधार लागू कर सकता है; इसे केवल-पढ़ने वाला रखने के लिए **N** जवाब दें।",
  "It installs to `/opt/oneuptime-vmware-agent`, writes a `0600` `.env` file and starts the agent with Docker Compose. Values are quoted for Docker Compose as they are written, so a password containing `$`, `#`, spaces or quotes works exactly as typed, and re-running the script reuses everything in an existing `.env` instead of prompting again.":
    "यह `/opt/oneuptime-vmware-agent` में इंस्टॉल होता है, `0600` वाली `.env` फ़ाइल लिखता है और Docker Compose से एजेंट शुरू करता है। मान Docker Compose के लिए वैसे ही उद्धरण चिह्नों में रखे जाते हैं जैसे लिखे गए हैं, इसलिए `$`, `#`, स्पेस या उद्धरण चिह्नों वाला पासवर्ड ठीक वैसे ही काम करता है जैसे आपने टाइप किया, और स्क्रिप्ट दोबारा चलाने पर वह फिर से पूछने के बजाय मौजूदा `.env` की हर चीज़ फिर से इस्तेमाल करती है।",
  "Look for `Everything is ready. Begin running and processing data.` in the logs — then give it one collection interval (2 minutes by default): nothing is sent until the first full inventory walk completes. The vCenter then appears automatically in the **VMware** section, with its datacenters, clusters, ESXi hosts, virtual machines, datastores and resource pools inventoried.":
    "लॉग में `Everything is ready. Begin running and processing data.` देखें — फिर इसे एक संग्रह अंतराल (डिफ़ॉल्ट 2 मिनट) दें: पहली पूरी इन्वेंटरी यात्रा पूरी होने तक कुछ नहीं भेजा जाता। इसके बाद vCenter अपने-आप **VMware** सेक्शन में दिखता है, उसके डेटा सेंटर, क्लस्टर, ESXi होस्ट, वर्चुअल मशीनें, डेटास्टोर और संसाधन पूल इन्वेंटरी में दर्ज होकर।",
  "`docker compose ps` also lists **`oneuptime-vmware-ai-agent`**, the OneUptime AI agent — see **OneUptime AI agent** under Advanced.":
    "`docker compose ps` में **`oneuptime-vmware-ai-agent`** भी दिखता है, जो OneUptime AI एजेंट है — उन्नत में **OneUptime AI एजेंट** देखें।",
  "**OneUptime AI agent (on by default, read-only).** AI investigations are on: it lets OneUptime AI investigate incidents and alerts on this vCenter with read-only `govc` commands, and changes nothing unless you allow fixes.":
    "**OneUptime AI एजेंट (डिफ़ॉल्ट रूप से चालू, केवल-पढ़ने वाला)।** AI जाँच चालू है: यह OneUptime AI को केवल-पढ़ने वाले `govc` कमांड से इस vCenter की घटनाओं और अलर्ट की जाँच करने देता है, और जब तक आप सुधारों की अनुमति न दें, कुछ नहीं बदलता।",
  "The install script writes these to `/opt/oneuptime-vmware-agent/.env`. After changing one, apply it with `docker compose up -d` in `/opt/oneuptime-vmware-agent`.":
    "इंस्टॉल स्क्रिप्ट इन्हें `/opt/oneuptime-vmware-agent/.env` में लिखती है। किसी एक को बदलने के बाद उसे `/opt/oneuptime-vmware-agent` में `docker compose up -d` से लागू करें।",
  "| Variable | Required | Description |": "| वेरिएबल | ज़रूरी | विवरण |",
  "| `ONEUPTIME_URL` | Yes | Your OneUptime instance URL (e.g. `<YOUR_ONEUPTIME_URL>`) |":
    "| `ONEUPTIME_URL` | हाँ | आपके OneUptime इंस्टेंस का URL (जैसे `<YOUR_ONEUPTIME_URL>`) |",
  "| `ONEUPTIME_TELEMETRY_INGESTION_KEY` | Yes | Telemetry ingestion key — the one picked in step 1 |":
    "| `ONEUPTIME_TELEMETRY_INGESTION_KEY` | हाँ | टेलीमेट्री इंजेशन कुंजी, वही जो चरण 1 में चुनी गई |",
  "| `VMWARE_VCENTER_NAME` | Yes | The name this vCenter registers under in OneUptime. Stamped on every metric as the `vmware.vcenter.name` resource attribute. Keep it stable — changing it registers a new vCenter (default: `vmware-vcenter`) |":
    "| `VMWARE_VCENTER_NAME` | हाँ | वह नाम जिससे यह vCenter OneUptime में दर्ज होता है। हर मेट्रिक पर `vmware.vcenter.name` रिसोर्स एट्रिब्यूट के रूप में लगता है। इसे स्थिर रखें — बदलने पर नया vCenter दर्ज होता है (डिफ़ॉल्ट: `vmware-vcenter`) |",
  "| `VCENTER_ENDPOINT` | Yes | Scheme + host of vCenter Server or a standalone ESXi host, **without** `/sdk`, e.g. `https://vcsa.example.com` |":
    "| `VCENTER_ENDPOINT` | हाँ | vCenter Server या स्वतंत्र ESXi होस्ट की स्कीम + होस्ट, `/sdk` के **बिना**, जैसे `https://vcsa.example.com` |",
  "| `VCENTER_USERNAME` | Yes | vSphere user with the Read-Only role, e.g. `oneuptime@vsphere.local` (or `DOMAIN\\user` for an Active Directory identity source) |":
    "| `VCENTER_USERNAME` | हाँ | Read-Only भूमिका वाला vSphere उपयोगकर्ता, जैसे `oneuptime@vsphere.local` (या Active Directory पहचान स्रोत के लिए `DOMAIN\\user`) |",
  "| `VCENTER_PASSWORD` | Yes | That user's password. If it contains `$`, `#`, spaces or quotes, single-quote it in `.env` (the install script does this for you) |":
    "| `VCENTER_PASSWORD` | हाँ | उस उपयोगकर्ता का पासवर्ड। अगर इसमें `$`, `#`, स्पेस या उद्धरण चिह्न हों, तो `.env` में इसे एकल उद्धरण चिह्नों में रखें (इंस्टॉल स्क्रिप्ट यह आपके लिए करती है) |",
  "| `VCENTER_INSECURE_SKIP_VERIFY` | No | `true` to accept vCenter's default self-signed (VMCA) certificate; `false` keeps TLS verification on (default: `false`) |":
    "| `VCENTER_INSECURE_SKIP_VERIFY` | नहीं | vCenter का डिफ़ॉल्ट स्व-हस्ताक्षरित (VMCA) प्रमाणपत्र स्वीकार करने के लिए `true`; `false` TLS सत्यापन चालू रखता है (डिफ़ॉल्ट: `false`) |",
  "| `VCENTER_COLLECTION_INTERVAL` | No | How often the whole inventory is polled. Raise to `5m` or `10m` for very large vCenters (default: `2m`) |":
    "| `VCENTER_COLLECTION_INTERVAL` | नहीं | पूरी इन्वेंटरी कितनी बार पूछी जाती है। बहुत बड़े vCenter के लिए इसे `5m` या `10m` तक बढ़ाएँ (डिफ़ॉल्ट: `2m`) |",
  "The OneUptime AI agent's own settings are under **OneUptime AI agent**.":
    "OneUptime AI एजेंट की अपनी सेटिंग **OneUptime AI एजेंट** में हैं।",
  "This is the `docker-compose.yml` the agent runs (the `.env` file supplies the values). The collector image is pinned; when a newer OneUptime release bumps the pin, download both files again before pulling:":
    "यह वह `docker-compose.yml` है जिसे एजेंट चलाता है (मान `.env` फ़ाइल देती है)। कलेक्टर इमेज पिन की गई है; जब OneUptime की नई रिलीज़ पिन बढ़ाए, तो पुल करने से पहले दोनों फ़ाइलें फिर से डाउनलोड करें:",
  "And the full `otel-collector-config.yaml`. The `resource` processor stamps the `vmware.vcenter.name` attribute that registers the vCenter in OneUptime and that every VMware page, monitor and alert template scopes on — keep it in place if you customize the config. The `batch` processor deliberately has no `send_batch_max_size`: OneUptime reads a whole collection per request to sum inventory counts and infer VM power state, so a collection must never be split across exports:":
    "और पूरी `otel-collector-config.yaml`। `resource` प्रोसेसर `vmware.vcenter.name` एट्रिब्यूट लगाता है, जिससे vCenter OneUptime में दर्ज होता है और जिस पर हर VMware पेज, मॉनिटर और अलर्ट टेम्पलेट सीमित रहता है — कॉन्फ़िग बदलें तो इसे बनाए रखें। `batch` प्रोसेसर में जानबूझकर कोई `send_batch_max_size` नहीं है: OneUptime इन्वेंटरी गिनतियाँ जोड़ने और VM की पावर स्थिति निकालने के लिए हर अनुरोध में पूरा एक संग्रह पढ़ता है, इसलिए किसी संग्रह को कभी कई एक्सपोर्ट में नहीं बँटना चाहिए:",
  "Every `VCENTER_COLLECTION_INTERVAL` the receiver walks the full vSphere inventory and emits one OpenTelemetry resource per object. Identity lives in **resource attributes** — `vcenter.datacenter.name`, `vcenter.cluster.name`, `vcenter.host.name`, `vcenter.vm.name` / `vcenter.vm.id`, `vcenter.datastore.name`, `vcenter.resource_pool.name` / `vcenter.resource_pool.inventory_path` — and the agent adds `vmware.vcenter.name` on top so OneUptime can route everything to your vCenter.":
    "हर `VCENTER_COLLECTION_INTERVAL` पर रिसीवर पूरी vSphere इन्वेंटरी से गुज़रता है और हर ऑब्जेक्ट के लिए एक OpenTelemetry रिसोर्स भेजता है। पहचान **रिसोर्स एट्रिब्यूट** में रहती है — `vcenter.datacenter.name`, `vcenter.cluster.name`, `vcenter.host.name`, `vcenter.vm.name` / `vcenter.vm.id`, `vcenter.datastore.name`, `vcenter.resource_pool.name` / `vcenter.resource_pool.inventory_path` — और एजेंट उसके ऊपर `vmware.vcenter.name` जोड़ता है ताकि OneUptime सब कुछ आपके vCenter तक पहुँचा सके।",
  "| vSphere object | Identity (resource attributes) | Metrics |":
    "| vSphere ऑब्जेक्ट | पहचान (रिसोर्स एट्रिब्यूट) | मेट्रिक |",
  "| **Datacenter** | `vcenter.datacenter.name` | `vcenter.datacenter.cluster.count{status}`, `.host.count{status,power_state}`, `.vm.count{status,power_state}`, `.datastore.count`, `.disk.space{disk_state}`, `.cpu.limit`, `.memory.limit` |":
    "| **डेटा सेंटर** | `vcenter.datacenter.name` | `vcenter.datacenter.cluster.count{status}`, `.host.count{status,power_state}`, `.vm.count{status,power_state}`, `.datastore.count`, `.disk.space{disk_state}`, `.cpu.limit`, `.memory.limit` |",
  "| **Cluster** | + `vcenter.cluster.name` | `vcenter.cluster.cpu.effective`, `.cpu.limit`, `.memory.effective`, `.memory.limit`, `.host.count{effective}`, `.vm.count{power_state}`, `.vm_template.count`, `vcenter.cluster.vsan.*` |":
    "| **क्लस्टर** | + `vcenter.cluster.name` | `vcenter.cluster.cpu.effective`, `.cpu.limit`, `.memory.effective`, `.memory.limit`, `.host.count{effective}`, `.vm.count{power_state}`, `.vm_template.count`, `vcenter.cluster.vsan.*` |",
  "| **ESXi host** | + `vcenter.host.name` (and `vcenter.cluster.name` when clustered) | `vcenter.host.cpu.usage` / `.capacity` / `.utilization` / `.reserved`, `.memory.usage` / `.utilization` / `.capacity`, `.disk.latency.avg` / `.latency.max` / `.throughput`, `.network.usage` / `.throughput` / `.packet.rate` / `.packet.drop.rate` / `.packet.error.rate`, `vcenter.host.vsan.*` |":
    "| **ESXi होस्ट** | + `vcenter.host.name` (और क्लस्टर में होने पर `vcenter.cluster.name`) | `vcenter.host.cpu.usage` / `.capacity` / `.utilization` / `.reserved`, `.memory.usage` / `.utilization` / `.capacity`, `.disk.latency.avg` / `.latency.max` / `.throughput`, `.network.usage` / `.throughput` / `.packet.rate` / `.packet.drop.rate` / `.packet.error.rate`, `vcenter.host.vsan.*` |",
  "| **Virtual machine** | + `vcenter.host.name`, `vcenter.vm.name`, `vcenter.vm.id` (instance UUID); `vcenter.resource_pool.*` or `vcenter.virtual_app.*` | `vcenter.vm.disk.usage{disk_state}`, `.disk.utilization`, `.memory.usage` / `.utilization` / `.ballooned` / `.swapped` / `.swapped_ssd`; **powered-on VMs only:** `.cpu.usage`, `.cpu.readiness`, `.cpu.utilization`, `.disk.latency.*` / `.throughput`, `.network.*`, `vcenter.vm.vsan.*` |":
    "| **वर्चुअल मशीन** | + `vcenter.host.name`, `vcenter.vm.name`, `vcenter.vm.id` (इंस्टेंस UUID); `vcenter.resource_pool.*` या `vcenter.virtual_app.*` | `vcenter.vm.disk.usage{disk_state}`, `.disk.utilization`, `.memory.usage` / `.utilization` / `.ballooned` / `.swapped` / `.swapped_ssd`; **केवल चालू VM:** `.cpu.usage`, `.cpu.readiness`, `.cpu.utilization`, `.disk.latency.*` / `.throughput`, `.network.*`, `vcenter.vm.vsan.*` |",
  "| **VM template** | `vcenter.vm_template.name`, `vcenter.vm_template.id` | `vcenter.vm.disk.usage{disk_state}` only |":
    "| **VM टेम्पलेट** | `vcenter.vm_template.name`, `vcenter.vm_template.id` | केवल `vcenter.vm.disk.usage{disk_state}` |",
  "| **Datastore** | + `vcenter.datastore.name` | `vcenter.datastore.disk.usage{disk_state}`, `.disk.utilization` |":
    "| **डेटास्टोर** | + `vcenter.datastore.name` | `vcenter.datastore.disk.usage{disk_state}`, `.disk.utilization` |",
  "| **Resource pool** | + `vcenter.resource_pool.name`, `vcenter.resource_pool.inventory_path` | `vcenter.resource_pool.cpu.usage` / `.cpu.shares`, `.memory.usage{type}` / `.memory.shares` / `.memory.ballooned` / `.memory.swapped` / `.memory.granted{type}` |":
    "| **संसाधन पूल** | + `vcenter.resource_pool.name`, `vcenter.resource_pool.inventory_path` | `vcenter.resource_pool.cpu.usage` / `.cpu.shares`, `.memory.usage{type}` / `.memory.shares` / `.memory.ballooned` / `.memory.swapped` / `.memory.granted{type}` |",
  "Datapoint attributes (`{...}` above) are what you filter and group by in monitor criteria: `direction` (`read`/`write`, `transmitted`/`received`), `disk_state` (`available`/`used`), `status` (`red`/`yellow`/`green`/`gray`), `effective` (`true`/`false`), `power_state` (`on`/`off`/`standby`/`suspended`/`unknown`), `object` (the NIC or disk instance), `cpu_reservation_type` (`total`/`used`) and `type`. In OneUptime, resource attributes are `resource.`-prefixed (`resource.vcenter.host.name`) and datapoint attributes are bare (`disk_state`). Units are the receiver's own: MHz for CPU usage and capacity, `%` for utilization and CPU readiness, MiB for host/VM/resource-pool memory, bytes for cluster and datacenter memory and all disk space, `ms` for disk latency and `µs` for vSAN latency.":
    "डेटा पॉइंट एट्रिब्यूट (ऊपर `{...}`) वे हैं जिनसे आप मॉनिटर मानदंडों में फ़िल्टर और समूह बनाते हैं: `direction` (`read`/`write`, `transmitted`/`received`), `disk_state` (`available`/`used`), `status` (`red`/`yellow`/`green`/`gray`), `effective` (`true`/`false`), `power_state` (`on`/`off`/`standby`/`suspended`/`unknown`), `object` (NIC या डिस्क इंस्टेंस), `cpu_reservation_type` (`total`/`used`) और `type`। OneUptime में रिसोर्स एट्रिब्यूट पर `resource.` उपसर्ग लगता है (`resource.vcenter.host.name`) और डेटा पॉइंट एट्रिब्यूट बिना उपसर्ग के होते हैं (`disk_state`)। इकाइयाँ रिसीवर की अपनी हैं: CPU उपयोग और क्षमता के लिए MHz, उपयोग दर और CPU रेडीनेस के लिए `%`, होस्ट/VM/संसाधन पूल की मेमोरी के लिए MiB, क्लस्टर और डेटा सेंटर की मेमोरी और सारी डिस्क जगह के लिए बाइट, डिस्क विलंब के लिए `ms` और vSAN विलंब के लिए `µs`।",
  "The receiver does not export a per-VM power-state metric. Instead it emits `vcenter.vm.cpu.*` **only for powered-on VMs**, so OneUptime infers the state from what arrived in each collection: a VM that reported CPU metrics is *powered on*; one that reported only memory and disk usage is *powered off* (or suspended — vSphere does not tell them apart here). This inference reads a whole collection at a time, which is why the shipped `batch` processor has a large `send_batch_size` and deliberately no `send_batch_max_size`: a collection split across two exports would zero inventory counts and flip VMs to off. Keep the batch settings as shipped.":
    "रिसीवर हर VM के लिए पावर-स्थिति मेट्रिक एक्सपोर्ट नहीं करता। इसके बजाय यह `vcenter.vm.cpu.*` **केवल चालू VM के लिए** भेजता है, इसलिए OneUptime हर संग्रह में जो आया उससे स्थिति निकालता है: जिस VM ने CPU मेट्रिक भेजे वह *चालू* है; जिसने केवल मेमोरी और डिस्क उपयोग भेजा वह *बंद* है (या निलंबित — vSphere यहाँ दोनों में फ़र्क नहीं करता)। यह अनुमान एक बार में पूरा संग्रह पढ़ता है, इसीलिए साथ आए `batch` प्रोसेसर में बड़ा `send_batch_size` है और जानबूझकर कोई `send_batch_max_size` नहीं: दो एक्सपोर्ट में बँटा संग्रह इन्वेंटरी गिनतियों को शून्य कर देगा और VM को बंद दिखा देगा। batch सेटिंग वैसी ही रखें जैसी आती हैं।",
  "By default the agent ships **metrics only** — the Logs tab of the vCenter dashboard stays empty until you enable a log receiver. The shipped config contains a commented-out `syslog` receiver pair (TCP and UDP on port 5514, RFC 3164 — ESXi's native format) wired to a commented `logs` pipeline that stamps `vmware.vcenter.name` so the logs land on this vCenter.":
    "डिफ़ॉल्ट रूप से एजेंट **केवल मेट्रिक** भेजता है — जब तक आप लॉग रिसीवर चालू न करें, vCenter डैशबोर्ड का लॉग टैब खाली रहता है। साथ आए कॉन्फ़िग में टिप्पणी किए गए `syslog` रिसीवरों की एक जोड़ी है (पोर्ट 5514 पर TCP और UDP, RFC 3164 — ESXi का अपना फ़ॉर्मैट), जो टिप्पणी की गई `logs` पाइपलाइन से जुड़ी है, जो `vmware.vcenter.name` लगाती है ताकि लॉग इस vCenter पर पहुँचें।",
  "1. **Uncomment the two `syslog/*` receivers and the `logs` pipeline** in `otel-collector-config.yaml`.":
    "1. `otel-collector-config.yaml` में **दोनों `syslog/*` रिसीवर और `logs` पाइपलाइन से टिप्पणी हटाएँ**।",
  "2. **Uncomment the `ports:` block** in `docker-compose.yml`, then apply it — and open the port on the machine's firewall for the ESXi management network:":
    "2. `docker-compose.yml` में **`ports:` ब्लॉक से टिप्पणी हटाएँ**, फिर उसे लागू करें — और ESXi प्रबंधन नेटवर्क के लिए मशीन के फ़ायरवॉल पर पोर्ट खोलें:",
  "3. **Point every ESXi host at the agent.** Select the host, open *Configure → System → Advanced System Settings*, set `Syslog.global.logHost` to `udp://<agent-host>:5514` (or `tcp://`), then allow the outbound traffic under *Configure → System → Firewall → Edit → syslog*. Or per host with `esxcli`:":
    "3. **हर ESXi होस्ट को एजेंट की ओर करें।** होस्ट चुनें, *Configure → System → Advanced System Settings* खोलें, `Syslog.global.logHost` को `udp://<agent-host>:5514` (या `tcp://`) पर सेट करें, फिर *Configure → System → Firewall → Edit → syslog* के अंतर्गत बाहर जाने वाले ट्रैफ़िक की अनुमति दें। या `esxcli` से हर होस्ट पर:",
  "Any resource attribute prefixed with `oneuptime.label.` is promoted to a project label and attached to the vCenter. Add the attributes to the `resource` processor in `otel-collector-config.yaml`, next to `vmware.vcenter.name`:":
    "`oneuptime.label.` उपसर्ग वाला कोई भी रिसोर्स एट्रिब्यूट प्रोजेक्ट लेबल बनकर vCenter से जुड़ जाता है। एट्रिब्यूट को `otel-collector-config.yaml` के `resource` प्रोसेसर में `vmware.vcenter.name` के बगल में जोड़ें:",
  "Then restart the collector so it reads the new config:":
    "फिर कलेक्टर को रीस्टार्ट करें ताकि वह नया कॉन्फ़िग पढ़े:",
  "The vCenter shows up tagged `team:platform` and `env:production`. Labels added manually in the OneUptime UI are never removed by the agent.":
    "vCenter `team:platform` और `env:production` टैग के साथ दिखता है। OneUptime UI में हाथ से जोड़े गए लेबल एजेंट कभी नहीं हटाता।",
  "`docker-compose.yml` also runs **`oneuptime-vmware-ai-agent`**. While OneUptime AI investigates an incident or alert on this vCenter, it runs `govc` commands through it — a VM's power state, the host it runs on, recent events and tasks, performance counters. It logs in with the vCenter credentials from the same `.env` (OneUptime never sends it any), registers as the vCenter named `VMWARE_VCENTER_NAME`, and appears on the vCenter's **AI → AI agent** page.":
    "`docker-compose.yml` **`oneuptime-vmware-ai-agent`** भी चलाता है। जब OneUptime AI इस vCenter की किसी घटना या अलर्ट की जाँच करता है, तो वह इसके ज़रिए `govc` कमांड चलाता है — किसी VM की पावर स्थिति, वह किस होस्ट पर चलती है, हाल की घटनाएँ और काम, परफ़ॉर्मेंस काउंटर। यह उसी `.env` के vCenter क्रेडेंशियल से लॉग इन करता है (OneUptime इसे कभी कोई क्रेडेंशियल नहीं भेजता), `VMWARE_VCENTER_NAME` नाम के vCenter के रूप में दर्ज होता है, और vCenter के **एआई → AI एजेंट** पेज पर दिखता है।",
  "- **The vSphere role is the hard limit.** With the collector's Read-Only user it can read and nothing else.":
    "- **vSphere भूमिका ही पक्की सीमा है।** कलेक्टर के Read-Only उपयोगकर्ता के साथ यह पढ़ सकता है और कुछ नहीं।",
  "- It is **read-only** unless you set `ONEUPTIME_AI_ALLOW_WRITES=true`. Fixes — powering a VM back on, a guest reboot — also need a vSphere user of its own whose role allows them, set as `ONEUPTIME_AI_VCENTER_USERNAME` / `ONEUPTIME_AI_VCENTER_PASSWORD`; the agent's README has the `govc` commands for that role. The install script asks about fixes on a fresh install and writes these settings for you.":
    "- यह **केवल-पढ़ने वाला** है, जब तक आप `ONEUPTIME_AI_ALLOW_WRITES=true` सेट न करें। सुधारों — किसी VM को फिर से चालू करना, गेस्ट को रीबूट करना — के लिए एक अलग vSphere उपयोगकर्ता भी चाहिए जिसकी भूमिका उन्हें अनुमति दे, जिसे `ONEUPTIME_AI_VCENTER_USERNAME` / `ONEUPTIME_AI_VCENTER_PASSWORD` के रूप में सेट किया जाता है; उस भूमिका के `govc` कमांड एजेंट के README में हैं। नए इंस्टॉल पर इंस्टॉल स्क्रिप्ट सुधारों के बारे में पूछती है और ये सेटिंग आपके लिए लिखती है।",
  "- It never changes the VM named after the host in `VCENTER_ENDPOINT` — normally the vCenter appliance. When the endpoint is an IP address, or the appliance's VM has another name, put that VM's name in `ONEUPTIME_AI_PROTECTED_TARGETS`, together with the VM the agent runs on.":
    "- यह कभी उस VM को नहीं बदलता जिसका नाम `VCENTER_ENDPOINT` के होस्ट पर है — आम तौर पर vCenter उपकरण। जब एंडपॉइंट एक IP पता हो, या उपकरण की VM का नाम कुछ और हो, तो उस VM का नाम, एजेंट जिस VM पर चलता है उसके साथ, `ONEUPTIME_AI_PROTECTED_TARGETS` में डालें।",
  "- Check it: `docker exec oneuptime-vmware-ai-agent wget -qO- http://127.0.0.1:3877/status`":
    "- इसे जाँचें: `docker exec oneuptime-vmware-ai-agent wget -qO- http://127.0.0.1:3877/status`",
  "- Not using OneUptime AI? Delete the `oneuptime-vmware-ai-agent` service from `docker-compose.yml`.":
    "- OneUptime AI इस्तेमाल नहीं करते? `docker-compose.yml` से `oneuptime-vmware-ai-agent` सर्विस हटा दें।",
  "What it may run and how fixes work: [Infrastructure AI Agents](/docs/ai/infrastructure-ai-agents#vmware-vcenter).":
    "यह क्या चला सकता है और सुधार कैसे काम करते हैं: [इन्फ़्रास्ट्रक्चर AI एजेंट](/docs/ai/infrastructure-ai-agents#vmware-vcenter)।",
  "**Upgrade** — re-run the install script. It reuses every value in your existing `.env` (nothing is prompted for again), downloads the latest `docker-compose.yml` and `otel-collector-config.yaml`, and recreates the agent with them:":
    "**अपग्रेड** — इंस्टॉल स्क्रिप्ट फिर से चलाएँ। यह आपकी मौजूदा `.env` का हर मान फिर से इस्तेमाल करती है (कुछ भी फिर से नहीं पूछा जाता), नवीनतम `docker-compose.yml` और `otel-collector-config.yaml` डाउनलोड करती है, और उनसे एजेंट को फिर से बनाती है:",
  "The config reports the collector version it pins as the vCenter's **Agent Version**. When this OneUptime pins a newer one, a warning sign beside it opens these commands.":
    "कॉन्फ़िग अपने पिन किए कलेक्टर संस्करण को vCenter के **एजेंट संस्करण** के रूप में बताता है। जब यह OneUptime नया संस्करण पिन करता है, तो उसके बगल का चेतावनी चिह्न ये कमांड खोलता है।",
  "**Uninstall:**": "**अनइंस्टॉल करें:**",
  "Then remove the `oneuptime` user's permission in vCenter (and the OneUptime AI fixes user's, if you created one) if you no longer need it.":
    "फिर, अगर अब ज़रूरत न हो, तो vCenter में `oneuptime` उपयोगकर्ता की अनुमति हटा दें (और अगर आपने OneUptime AI सुधार उपयोगकर्ता बनाया था, तो उसकी भी)।",
  "`troubleshoot.sh` checks the whole chain — container runtime, vCenter reachability and credentials, vCenter-name stamping, token shape, collector self-metrics — and asks OneUptime directly whether it accepts your ingestion key. That last check matters most: OneUptime's OTLP endpoints refuse a bad key with `401` or `422`, which the collector logs as a single `Exporting failed` line per batch that is easy to miss, so the script asks `GET /otlp/v1/validate` for a direct 200/401 verdict.":
    "`troubleshoot.sh` पूरी कड़ी जाँचती है — कंटेनर रनटाइम, vCenter तक पहुँच और क्रेडेंशियल, vCenter नाम का लगना, टोकन का आकार, कलेक्टर के अपने मेट्रिक — और सीधे OneUptime से पूछती है कि क्या वह आपकी इंजेशन कुंजी स्वीकार करता है। यही आख़िरी जाँच सबसे अहम है: OneUptime के OTLP एंडपॉइंट ग़लत कुंजी को `401` या `422` से अस्वीकार करते हैं, जिसे कलेक्टर हर batch पर एक ही `Exporting failed` पंक्ति के रूप में लॉग करता है जो आसानी से छूट जाती है, इसलिए स्क्रिप्ट `GET /otlp/v1/validate` से सीधा 200/401 फ़ैसला माँगती है।",
  "It ends with a verdict naming the most likely cause.":
    "यह सबसे संभावित कारण बताने वाले फ़ैसले के साथ ख़त्म होता है।",
  "1. Check that the agent is running (in `/opt/oneuptime-vmware-agent`): `docker compose ps`":
    "1. जाँचें कि एजेंट चल रहा है (`/opt/oneuptime-vmware-agent` में): `docker compose ps`",
  "2. Check the agent logs for errors: `docker compose logs oneuptime-vmware-agent | grep -i error`":
    "2. एजेंट के लॉग में त्रुटियाँ जाँचें: `docker compose logs oneuptime-vmware-agent | grep -i error`",
  "3. Verify your OneUptime URL and ingestion key are correct.":
    "3. पुष्टि करें कि आपका OneUptime URL और इंजेशन कुंजी सही हैं।",
  "4. Ensure the agent machine can reach the OneUptime instance over the network.":
    "4. पक्का करें कि एजेंट की मशीन नेटवर्क पर OneUptime इंस्टेंस तक पहुँच सकती है।",
  "1. Check the collector logs: a login error (`incorrect user name or password`, `InvalidLogin`) means bad credentials — or a password containing `$`, `#`, spaces or quotes that is not single-quoted in `.env` (Docker Compose expands `$VAR` and treats a space followed by `#` as a comment otherwise), `x509: certificate signed by unknown authority` means TLS verification is on against a self-signed certificate (set `VCENTER_INSECURE_SKIP_VERIFY=true`), `connection refused` / `no such host` means a wrong `VCENTER_ENDPOINT`.":
    "1. कलेक्टर के लॉग जाँचें: लॉगिन त्रुटि (`incorrect user name or password`, `InvalidLogin`) का मतलब है ग़लत क्रेडेंशियल — या `$`, `#`, स्पेस या उद्धरण चिह्नों वाला ऐसा पासवर्ड जो `.env` में एकल उद्धरण चिह्नों में नहीं है (वरना Docker Compose `$VAR` को फैला देता है और स्पेस के बाद आए `#` को टिप्पणी मानता है); `x509: certificate signed by unknown authority` का मतलब है कि स्व-हस्ताक्षरित प्रमाणपत्र के सामने TLS सत्यापन चालू है (`VCENTER_INSECURE_SKIP_VERIFY=true` सेट करें); `connection refused` / `no such host` का मतलब है ग़लत `VCENTER_ENDPOINT`।",
  "2. Verify the endpoint is reachable from the agent's network (the collector image is distroless, so test from alongside it) — you should see an XML document advertising `urn:vim25`:":
    "2. पुष्टि करें कि एजेंट के नेटवर्क से एंडपॉइंट तक पहुँचा जा सकता है (कलेक्टर इमेज distroless है, इसलिए उसके बगल की मशीन से जाँचें) — आपको `urn:vim25` बताने वाला एक XML दस्तावेज़ दिखना चाहिए:",
  "3. Make sure `VMWARE_VCENTER_NAME` is set — discovery keys on the `vmware.vcenter.name` resource attribute.":
    "3. पक्का करें कि `VMWARE_VCENTER_NAME` सेट है — पहचान `vmware.vcenter.name` रिसोर्स एट्रिब्यूट पर टिकी है।",
  "4. Give it one collection interval: nothing is sent until the first full inventory walk completes.":
    "4. इसे एक संग्रह अंतराल दें: पहली पूरी इन्वेंटरी यात्रा पूरी होने तक कुछ नहीं भेजा जाता।",
  "Use the full principal — `oneuptime@vsphere.local`, or `DOMAIN\\user` / `user@domain.example` for an Active Directory identity source — and check how the password is written in `.env`. Docker Compose expands `$VAR` references in unquoted and double-quoted values and treats a space followed by `#` as the start of a comment, so a password containing `$`, `#`, spaces or quotes must be **single-quoted** — `VCENTER_PASSWORD='p@ss$word'`, which is what the install script writes. A password that itself contains a single quote goes in double quotes, with every `$` written as `$$` and `\"` / `\\` escaped with a backslash. A locked account (too many failed attempts) rejects a correct password too; check *Administration → Single Sign On → Users and Groups*.":
    "पूरा प्रिंसिपल इस्तेमाल करें — `oneuptime@vsphere.local`, या Active Directory पहचान स्रोत के लिए `DOMAIN\\user` / `user@domain.example` — और जाँचें कि `.env` में पासवर्ड कैसे लिखा है। Docker Compose बिना उद्धरण चिह्न वाले और दोहरे उद्धरण चिह्नों वाले मानों में `$VAR` संदर्भों को फैला देता है और स्पेस के बाद आए `#` को टिप्पणी की शुरुआत मानता है, इसलिए `$`, `#`, स्पेस या उद्धरण चिह्नों वाला पासवर्ड **एकल उद्धरण चिह्नों में** होना चाहिए — `VCENTER_PASSWORD='p@ss$word'`, और इंस्टॉल स्क्रिप्ट यही लिखती है। जिस पासवर्ड में ख़ुद एकल उद्धरण चिह्न हो, वह दोहरे उद्धरण चिह्नों में जाता है, हर `$` को `$$` लिखकर और `\"` / `\\` को बैकस्लैश से एस्केप करके। लॉक हुआ खाता (बहुत ज़्यादा असफल प्रयास) सही पासवर्ड भी अस्वीकार करता है; *Administration → Single Sign On → Users and Groups* जाँचें।",
  "vCenter appliances present a certificate issued by their own VMCA, which no Docker image trusts. Either set `VCENTER_INSECURE_SKIP_VERIFY=true` (the pragmatic choice on a private management network) or replace vCenter's machine certificate with one issued by a CA the collector image trusts. Do **not** point the endpoint at an `http://` URL — vCenter only serves the SDK over HTTPS.":
    "vCenter उपकरण अपने ही VMCA से जारी प्रमाणपत्र दिखाते हैं, जिस पर कोई Docker इमेज भरोसा नहीं करती। या तो `VCENTER_INSECURE_SKIP_VERIFY=true` सेट करें (निजी प्रबंधन नेटवर्क पर यह व्यावहारिक विकल्प है) या vCenter के मशीन प्रमाणपत्र को ऐसे CA से जारी प्रमाणपत्र से बदलें जिस पर कलेक्टर इमेज भरोसा करती हो। एंडपॉइंट को `http://` URL पर **न** रखें — vCenter SDK केवल HTTPS पर देता है।",
  "The Read-Only role was granted on the vCenter object without **Propagate to children**, or on a narrower object than the vCenter root. Objects the user cannot see are silently absent. Fix the permission on the top-level vCenter object with propagation enabled; the next collection fills in the inventory.":
    "Read-Only भूमिका vCenter ऑब्जेक्ट पर **Propagate to children** के बिना दी गई थी, या vCenter रूट से संकरे किसी ऑब्जेक्ट पर। जिन ऑब्जेक्ट को उपयोगकर्ता नहीं देख सकता, वे चुपचाप गायब रहते हैं। सबसे ऊपर के vCenter ऑब्जेक्ट पर प्रसार चालू करके अनुमति ठीक करें; अगला संग्रह इन्वेंटरी भर देता है।",
  "VM power state is inferred from the `vcenter.vm.cpu.*` datapoints arriving in the same collection as the VM's memory and disk datapoints (see **How VM power state is worked out** under Advanced). If you customized the `batch` processor and added a `send_batch_max_size`, a large inventory is split across exports and the CPU datapoints land in a different request — restore the shipped batch settings.":
    "VM की पावर स्थिति इस बात से निकाली जाती है कि `vcenter.vm.cpu.*` डेटा पॉइंट उसी संग्रह में आते हैं या नहीं जिसमें VM के मेमोरी और डिस्क डेटा पॉइंट आते हैं (उन्नत में **VM की पावर स्थिति कैसे तय होती है** देखें)। अगर आपने `batch` प्रोसेसर बदलकर `send_batch_max_size` जोड़ा है, तो बड़ी इन्वेंटरी कई एक्सपोर्ट में बँट जाती है और CPU डेटा पॉइंट किसी दूसरे अनुरोध में पहुँचते हैं — साथ आई batch सेटिंग वापस लाएँ।",
  "Each collection is a full walk of the inventory plus one performance query per object batch. For vCenters with thousands of VMs raise `VCENTER_COLLECTION_INTERVAL` to `5m` or `10m` (a collection that takes longer than the interval is skipped, not overlapped), match `max_query_metrics` to your vCenter's `vpxd.stats.maxQueryMetrics` if the log reports `The maximum number of performance metrics per query exceeded`, and raise `limit_mib` if the memory limiter reports dropped data.":
    "हर संग्रह इन्वेंटरी की पूरी यात्रा है, साथ में हर ऑब्जेक्ट बैच के लिए एक परफ़ॉर्मेंस क्वेरी। हज़ारों VM वाले vCenter के लिए `VCENTER_COLLECTION_INTERVAL` को `5m` या `10m` तक बढ़ाएँ (अंतराल से लंबा चलने वाला संग्रह छोड़ दिया जाता है, एक-दूसरे पर नहीं चढ़ता), अगर लॉग `The maximum number of performance metrics per query exceeded` बताए तो `max_query_metrics` को अपने vCenter के `vpxd.stats.maxQueryMetrics` के बराबर करें, और अगर मेमोरी लिमिटर छोड़ा गया डेटा बताए तो `limit_mib` बढ़ाएँ।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. Fix it in `.env` and apply it with `docker compose up -d` in `/opt/oneuptime-vmware-agent` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। इसे `.env` में ठीक करें और `/opt/oneuptime-vmware-agent` में `docker compose up -d` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
  "- **vCenter name** — enter **`vcenter-1`** exactly; a different name registers a new vCenter.":
    "- **vCenter का नाम**: ठीक **`vcenter-1`** लिखें; अलग नाम एक नया vCenter दर्ज करता है।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. This vCenter is **`vcenter-1`**. Fix it in `.env` and apply it with `docker compose up -d` in `/opt/oneuptime-vmware-agent` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। यह vCenter **`vcenter-1`** है। इसे `.env` में ठीक करें और `/opt/oneuptime-vmware-agent` में `docker compose up -d` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
  "The command already carries your OneUptime URL and ingestion key. The script asks for the rest:":
    "कमांड में आपका OneUptime URL और इंजेशन कुंजी पहले से हैं। बाकी स्क्रिप्ट पूछती है:",
  "Download `docker-compose.yml` and `otel-collector-config.yaml` from this OneUptime into a new folder:":
    "इस OneUptime से `docker-compose.yml` और `otel-collector-config.yaml` एक नए फ़ोल्डर में डाउनलोड करें:",
  "Create a `.env` file next to them:": "उनके बगल में एक `.env` फ़ाइल बनाएँ:",
  "- Replace `my-vcenter` with a name for this vCenter, such as `vcenter-prod`. It is how the vCenter appears in OneUptime, so keep it stable: a new name registers a new vCenter.":
    "- `my-vcenter` को इस vCenter के किसी नाम से बदलें, जैसे `vcenter-prod`। OneUptime में vCenter इसी नाम से दिखता है, इसलिए इसे स्थिर रखें: नया नाम एक नया vCenter दर्ज करता है।",
  "- Set `VCENTER_ENDPOINT` to the scheme and host of your vCenter, or of a standalone ESXi host, **without** `/sdk`.":
    "- `VCENTER_ENDPOINT` को अपने vCenter, या किसी स्वतंत्र ESXi होस्ट, की स्कीम और होस्ट पर सेट करें, `/sdk` के **बिना**।",
  "- Keep the password in single quotes: Docker Compose expands `$` and treats a space followed by `#` as a comment in unquoted values.":
    "- पासवर्ड को एकल उद्धरण चिह्नों में रखें: बिना उद्धरण चिह्न वाले मानों में Docker Compose `$` को फैला देता है और स्पेस के बाद आए `#` को टिप्पणी मानता है।",
  "- `VCENTER_INSECURE_SKIP_VERIFY=true` accepts vCenter's default self-signed (VMCA) certificate.":
    "- `VCENTER_INSECURE_SKIP_VERIFY=true` vCenter का डिफ़ॉल्ट स्व-हस्ताक्षरित (VMCA) प्रमाणपत्र स्वीकार करता है।",
  "It holds a password, so make it private, then start the agent:":
    "इसमें पासवर्ड है, इसलिए इसे निजी बनाएँ, फिर एजेंट शुरू करें:",
  "Pick an ingestion key in step 1 to fill in `<YOUR_API_KEY>`.":
    "`<YOUR_API_KEY>` भरने के लिए चरण 1 में एक इंजेशन कुंजी चुनें।",
  "The agent reads these from the `.env` file next to `docker-compose.yml`. After changing one, apply it with `docker compose up -d` in the folder with `docker-compose.yml`.":
    "एजेंट इन्हें `docker-compose.yml` के बगल वाली `.env` फ़ाइल से पढ़ता है। किसी एक को बदलने के बाद उसे `docker-compose.yml` वाले फ़ोल्डर में `docker compose up -d` से लागू करें।",
  "| `VCENTER_PASSWORD` | Yes | That user's password. If it contains `$`, `#`, spaces or quotes, single-quote it in `.env` — see **vCenter rejects the login** under Troubleshooting |":
    "| `VCENTER_PASSWORD` | हाँ | उस उपयोगकर्ता का पासवर्ड। अगर इसमें `$`, `#`, स्पेस या उद्धरण चिह्न हों, तो `.env` में इसे एकल उद्धरण चिह्नों में रखें — समस्या निवारण में **vCenter लॉगिन अस्वीकार करता है** देखें |",
  "- It is **read-only** unless you set `ONEUPTIME_AI_ALLOW_WRITES=true`. Fixes — powering a VM back on, a guest reboot — also need a vSphere user of its own whose role allows them, set as `ONEUPTIME_AI_VCENTER_USERNAME` / `ONEUPTIME_AI_VCENTER_PASSWORD`; the agent's README has the `govc` commands for that role. Set them in `.env` and run `docker compose up -d`.":
    "- यह **केवल-पढ़ने वाला** है, जब तक आप `ONEUPTIME_AI_ALLOW_WRITES=true` सेट न करें। सुधारों — किसी VM को फिर से चालू करना, गेस्ट को रीबूट करना — के लिए एक अलग vSphere उपयोगकर्ता भी चाहिए जिसकी भूमिका उन्हें अनुमति दे, जिसे `ONEUPTIME_AI_VCENTER_USERNAME` / `ONEUPTIME_AI_VCENTER_PASSWORD` के रूप में सेट किया जाता है; उस भूमिका के `govc` कमांड एजेंट के README में हैं। इन्हें `.env` में सेट करें और `docker compose up -d` चलाएँ।",
  "Run these in the agent's folder, the one with `docker-compose.yml`.":
    "इन्हें एजेंट के फ़ोल्डर में चलाएँ, जिसमें `docker-compose.yml` है।",
  "**Upgrade** — the collector image is pinned in `docker-compose.yml` and its config is a file beside it, so pulling alone does not move the agent forward. Download `docker-compose.yml` and `otel-collector-config.yaml` again; your `.env` stays, and a change you made to either file has to be made again:":
    "**अपग्रेड** — कलेक्टर इमेज `docker-compose.yml` में पिन है और उसका कॉन्फ़िग बगल की एक फ़ाइल है, इसलिए केवल पुल करने से एजेंट आगे नहीं बढ़ता। `docker-compose.yml` और `otel-collector-config.yaml` फिर से डाउनलोड करें; आपकी `.env` बनी रहती है, और दोनों में से किसी फ़ाइल में किया गया बदलाव फिर से करना होगा:",
  "Then pull the images and recreate the agent, so the collector reads its new config:":
    "फिर इमेज पुल करें और एजेंट को फिर से बनाएँ, ताकि कलेक्टर अपना नया कॉन्फ़िग पढ़े:",
  "1. Check that the agent is running (in the agent's folder): `docker compose ps`":
    "1. जाँचें कि एजेंट चल रहा है (एजेंट के फ़ोल्डर में): `docker compose ps`",
  "Use the full principal — `oneuptime@vsphere.local`, or `DOMAIN\\user` / `user@domain.example` for an Active Directory identity source — and check how the password is written in `.env`. Docker Compose expands `$VAR` references in unquoted and double-quoted values and treats a space followed by `#` as the start of a comment, so a password containing `$`, `#`, spaces or quotes must be **single-quoted** — `VCENTER_PASSWORD='p@ss$word'`. A password that itself contains a single quote goes in double quotes, with every `$` written as `$$` and `\"` / `\\` escaped with a backslash. A locked account (too many failed attempts) rejects a correct password too; check *Administration → Single Sign On → Users and Groups*.":
    "पूरा प्रिंसिपल इस्तेमाल करें — `oneuptime@vsphere.local`, या Active Directory पहचान स्रोत के लिए `DOMAIN\\user` / `user@domain.example` — और जाँचें कि `.env` में पासवर्ड कैसे लिखा है। Docker Compose बिना उद्धरण चिह्न वाले और दोहरे उद्धरण चिह्नों वाले मानों में `$VAR` संदर्भों को फैला देता है और स्पेस के बाद आए `#` को टिप्पणी की शुरुआत मानता है, इसलिए `$`, `#`, स्पेस या उद्धरण चिह्नों वाला पासवर्ड **एकल उद्धरण चिह्नों में** होना चाहिए — `VCENTER_PASSWORD='p@ss$word'`। जिस पासवर्ड में ख़ुद एकल उद्धरण चिह्न हो, वह दोहरे उद्धरण चिह्नों में जाता है, हर `$` को `$$` लिखकर और `\"` / `\\` को बैकस्लैश से एस्केप करके। लॉक हुआ खाता (बहुत ज़्यादा असफल प्रयास) सही पासवर्ड भी अस्वीकार करता है; *Administration → Single Sign On → Users and Groups* जाँचें।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. Fix it in `.env` and apply it with `docker compose up -d` in the folder with `docker-compose.yml` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। इसे `.env` में ठीक करें और `docker-compose.yml` वाले फ़ोल्डर में `docker compose up -d` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
  "- This installs the agent for **`vcenter-1`** — keep `VMWARE_VCENTER_NAME` exactly as it is, or the data registers as a new vCenter.":
    "- यह **`vcenter-1`** के लिए एजेंट इंस्टॉल करता है — `VMWARE_VCENTER_NAME` को ठीक वैसा ही रखें, वरना डेटा एक नए vCenter के रूप में दर्ज होगा।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. This vCenter is **`vcenter-1`**. Fix it in `.env` and apply it with `docker compose up -d` in the folder with `docker-compose.yml` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। यह vCenter **`vcenter-1`** है। इसे `.env` में ठीक करें और `docker-compose.yml` वाले फ़ोल्डर में `docker compose up -d` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
  "A Linux machine (x86_64 or arm64) with systemd 235 or later — Ubuntu 18.04, Debian 10, RHEL 8 or newer — and `sudo`, that can reach vCenter over HTTPS (TCP 443) — ideally not a VM on the cluster it watches":
    "systemd 235 या नए (Ubuntu 18.04, Debian 10, RHEL 8 या नए) और `sudo` वाली एक Linux मशीन (x86_64 या arm64), जो HTTPS (TCP 443) पर vCenter तक पहुँच सके — बेहतर है कि वह उसी क्लस्टर की VM न हो जिस पर वह नज़र रखती है",
  "Run these on the Linux machine that will host the agent. They download `otelcol-contrib` 0.165.0 — the release of the upstream OpenTelemetry Collector the agent pins — with the agent's `otel-collector-config.yaml` and its systemd unit from this OneUptime, and install them to `/opt/oneuptime-vmware-agent`:":
    "इन्हें उस Linux मशीन पर चलाएँ जिस पर एजेंट रहेगा। ये इस OneUptime से `otelcol-contrib` 0.165.0 — upstream OpenTelemetry Collector की वह रिलीज़ जिसे एजेंट पिन करता है — एजेंट की `otel-collector-config.yaml` और उसकी systemd यूनिट के साथ डाउनलोड करते हैं, और उन्हें `/opt/oneuptime-vmware-agent` में इंस्टॉल करते हैं:",
  "The agent's settings go in `/opt/oneuptime-vmware-agent/.env`. It holds a password, so make it readable by root alone, then open it (`sudoedit` uses your `$EDITOR`):":
    "एजेंट की सेटिंग `/opt/oneuptime-vmware-agent/.env` में जाती हैं। इसमें पासवर्ड है, इसलिए इसे केवल root के पढ़ने लायक बनाएँ, फिर इसे खोलें (`sudoedit` आपका `$EDITOR` इस्तेमाल करता है):",
  "Put this in it:": "इसमें यह डालें:",
  '- Keep the user name and the password in double quotes, with each `\\` written `\\\\` and each `"` written `\\"` — `DOMAIN\\user` is `"DOMAIN\\\\user"` — while `$`, `#`, `\'` and spaces go in as they are. systemd reads this file, not a shell, and this is the form every systemd version reads the same: older ones (RHEL 8\'s, for one) drop a backslash even inside single quotes.':
    '- उपयोगकर्ता नाम और पासवर्ड को दोहरे उद्धरण चिह्नों में रखें, हर `\\` को `\\\\` और हर `"` को `\\"` लिखकर — `DOMAIN\\user` बनता है `"DOMAIN\\\\user"` — जबकि `$`, `#`, `\'` और स्पेस वैसे ही जाते हैं। इस फ़ाइल को शेल नहीं, systemd पढ़ता है, और यही वह रूप है जिसे systemd का हर संस्करण एक जैसा पढ़ता है: पुराने संस्करण (जैसे RHEL 8 वाला) एकल उद्धरण चिह्नों के अंदर भी बैकस्लैश हटा देते हैं।',
  "Then start the agent, and have it start on every boot:":
    "फिर एजेंट शुरू करें, और उसे हर बूट पर शुरू होने दें:",
  "systemd runs the collector as a throwaway unprivileged user, with no capabilities and nothing it can write to. This install runs the collector alone: the OneUptime AI agent ships only as a container image — see **OneUptime AI agent** under Advanced.":
    "systemd कलेक्टर को एक अस्थायी बिना-विशेषाधिकार उपयोगकर्ता के रूप में चलाता है, बिना किसी capabilities के और बिना किसी ऐसी जगह के जहाँ वह लिख सके। यह इंस्टॉल केवल कलेक्टर चलाता है: OneUptime AI एजेंट केवल कंटेनर इमेज के रूप में आता है — उन्नत में **OneUptime AI एजेंट** देखें।",
  "The service should be `active (running)`. Look for `Everything is ready. Begin running and processing data.` in the log — then give it one collection interval (2 minutes by default): nothing is sent until the first full inventory walk completes. The vCenter then appears automatically in the **VMware** section, with its datacenters, clusters, ESXi hosts, virtual machines, datastores and resource pools inventoried.":
    "सर्विस `active (running)` होनी चाहिए। लॉग में `Everything is ready. Begin running and processing data.` देखें — फिर इसे एक संग्रह अंतराल (डिफ़ॉल्ट 2 मिनट) दें: पहली पूरी इन्वेंटरी यात्रा पूरी होने तक कुछ नहीं भेजा जाता। इसके बाद vCenter अपने-आप **VMware** सेक्शन में दिखता है, उसके डेटा सेंटर, क्लस्टर, ESXi होस्ट, वर्चुअल मशीनें, डेटास्टोर और संसाधन पूल इन्वेंटरी में दर्ज होकर।",
  "The service reads these from `/opt/oneuptime-vmware-agent/.env`, the defaults included: its systemd unit sets them when the file leaves them out. After changing one, apply it with `sudo systemctl restart oneuptime-vmware-agent`.":
    "सर्विस इन्हें `/opt/oneuptime-vmware-agent/.env` से पढ़ती है, डिफ़ॉल्ट मान समेत: फ़ाइल में जो छूटा हो उसे उसकी systemd यूनिट सेट करती है। किसी एक को बदलने के बाद उसे `sudo systemctl restart oneuptime-vmware-agent` से लागू करें।",
  "| `VCENTER_USERNAME` | Yes | vSphere user with the Read-Only role, e.g. `oneuptime@vsphere.local` (or `DOMAIN\\user` for an Active Directory identity source), double-quoted in `.env` with each `\\` written `\\\\` |":
    "| `VCENTER_USERNAME` | हाँ | Read-Only भूमिका वाला vSphere उपयोगकर्ता, जैसे `oneuptime@vsphere.local` (या Active Directory पहचान स्रोत के लिए `DOMAIN\\user`), `.env` में दोहरे उद्धरण चिह्नों में, हर `\\` को `\\\\` लिखकर |",
  '| `VCENTER_PASSWORD` | Yes | That user\'s password, double-quoted in `.env` with each `\\` written `\\\\` and each `"` written `\\"`, the form every systemd version reads as typed — see **vCenter rejects the login** under Troubleshooting |':
    '| `VCENTER_PASSWORD` | हाँ | उस उपयोगकर्ता का पासवर्ड, `.env` में दोहरे उद्धरण चिह्नों में, हर `\\` को `\\\\` और हर `"` को `\\"` लिखकर — वह रूप जिसे systemd का हर संस्करण टाइप किए अनुसार पढ़ता है — समस्या निवारण में **vCenter लॉगिन अस्वीकार करता है** देखें |',
  "This is the systemd unit the agent runs, installed as `/etc/systemd/system/oneuptime-vmware-agent.service` (`/opt/oneuptime-vmware-agent/.env` supplies the values). It runs the collector as a throwaway unprivileged user with no capabilities, and serves the collector's own metrics on `127.0.0.1:8890` rather than the usual `8888`, so the agent runs beside another OpenTelemetry Collector on the same machine:":
    "यह वह systemd यूनिट है जिसे एजेंट चलाता है, `/etc/systemd/system/oneuptime-vmware-agent.service` के रूप में इंस्टॉल (`/opt/oneuptime-vmware-agent/.env` मान देती है)। यह कलेक्टर को बिना capabilities वाले एक अस्थायी बिना-विशेषाधिकार उपयोगकर्ता के रूप में चलाती है, और कलेक्टर के अपने मेट्रिक सामान्य `8888` के बजाय `127.0.0.1:8890` पर देती है, ताकि एजेंट उसी मशीन पर किसी दूसरे OpenTelemetry Collector के बगल में चल सके:",
  "And the full `otel-collector-config.yaml`, in `/opt/oneuptime-vmware-agent` — the same file the Docker install runs. The `resource` processor stamps the `vmware.vcenter.name` attribute that registers the vCenter in OneUptime and that every VMware page, monitor and alert template scopes on — keep it in place if you customize the config. The `batch` processor deliberately has no `send_batch_max_size`: OneUptime reads a whole collection per request to sum inventory counts and infer VM power state, so a collection must never be split across exports:":
    "और पूरी `otel-collector-config.yaml`, `/opt/oneuptime-vmware-agent` में — वही फ़ाइल जो Docker इंस्टॉल चलाता है। `resource` प्रोसेसर `vmware.vcenter.name` एट्रिब्यूट लगाता है, जिससे vCenter OneUptime में दर्ज होता है और जिस पर हर VMware पेज, मॉनिटर और अलर्ट टेम्पलेट सीमित रहता है — कॉन्फ़िग बदलें तो इसे बनाए रखें। `batch` प्रोसेसर में जानबूझकर कोई `send_batch_max_size` नहीं है: OneUptime इन्वेंटरी गिनतियाँ जोड़ने और VM की पावर स्थिति निकालने के लिए हर अनुरोध में पूरा एक संग्रह पढ़ता है, इसलिए किसी संग्रह को कभी कई एक्सपोर्ट में नहीं बँटना चाहिए:",
  "1. **Uncomment the two `syslog/*` receivers and the `logs` pipeline** in `/opt/oneuptime-vmware-agent/otel-collector-config.yaml` (`sudoedit` it).":
    "1. `/opt/oneuptime-vmware-agent/otel-collector-config.yaml` में **दोनों `syslog/*` रिसीवर और `logs` पाइपलाइन से टिप्पणी हटाएँ** (इसे `sudoedit` से खोलें)।",
  "2. **Restart the agent** — the collector listens on this machine itself, so there is no port to publish — and open port 5514 (TCP and UDP) on the machine's firewall for the ESXi management network:":
    "2. **एजेंट को रीस्टार्ट करें** — कलेक्टर इसी मशीन पर सुनता है, इसलिए कोई पोर्ट प्रकाशित नहीं करना — और ESXi प्रबंधन नेटवर्क के लिए मशीन के फ़ायरवॉल पर पोर्ट 5514 (TCP और UDP) खोलें:",
  "The OneUptime AI agent runs the read-only `govc` commands OneUptime AI asks for while it investigates an incident or alert on this vCenter — a VM's power state, the host it runs on, recent events and tasks, performance counters. It ships only as a container image (`oneuptime/resource-ai-agent`), so an install without Docker runs the collector alone. Inventory, metrics, monitors, alerts and syslog work the same without it.":
    "OneUptime AI एजेंट वे केवल-पढ़ने वाले `govc` कमांड चलाता है जो OneUptime AI इस vCenter की किसी घटना या अलर्ट की जाँच करते समय माँगता है — किसी VM की पावर स्थिति, वह किस होस्ट पर चलती है, हाल की घटनाएँ और काम, परफ़ॉर्मेंस काउंटर। यह केवल कंटेनर इमेज (`oneuptime/resource-ai-agent`) के रूप में आता है, इसलिए Docker के बिना इंस्टॉल केवल कलेक्टर चलाता है। इन्वेंटरी, मेट्रिक, मॉनिटर, अलर्ट और syslog इसके बिना भी वैसे ही काम करते हैं।",
  "To add it, run it with Docker on any machine that can reach vCenter. Download the agent's `docker-compose.yml`, write a `.env` next to it with the settings of `/opt/oneuptime-vmware-agent/.env` — quoted the Docker Compose way, in single quotes, since Docker Compose expands `$` in double quotes — and start the AI agent alone, not the collector beside it in that file, or every metric would arrive twice:":
    "इसे जोड़ने के लिए, इसे Docker के साथ किसी भी ऐसी मशीन पर चलाएँ जो vCenter तक पहुँच सके। एजेंट की `docker-compose.yml` डाउनलोड करें, उसके बगल में `/opt/oneuptime-vmware-agent/.env` की सेटिंग वाली एक `.env` लिखें — Docker Compose के तरीके से, एकल उद्धरण चिह्नों में, क्योंकि Docker Compose दोहरे उद्धरण चिह्नों में `$` को फैला देता है — और केवल AI एजेंट शुरू करें, उस फ़ाइल में उसके बगल वाला कलेक्टर नहीं, वरना हर मेट्रिक दो बार पहुँचेगा:",
  "It registers as the vCenter named `VMWARE_VCENTER_NAME` — the one this collector reports into — and appears on the vCenter's **AI → AI agent** page. It is **read-only** unless you set `ONEUPTIME_AI_ALLOW_WRITES=true` in that `.env`. What it may run and how fixes work: [Infrastructure AI Agents](/docs/ai/infrastructure-ai-agents#vmware-vcenter).":
    "यह `VMWARE_VCENTER_NAME` नाम के vCenter के रूप में दर्ज होता है — वही जिसमें यह कलेक्टर रिपोर्ट करता है — और vCenter के **एआई → AI एजेंट** पेज पर दिखता है। यह **केवल-पढ़ने वाला** है, जब तक आप उस `.env` में `ONEUPTIME_AI_ALLOW_WRITES=true` सेट न करें। यह क्या चला सकता है और सुधार कैसे काम करते हैं: [इन्फ़्रास्ट्रक्चर AI एजेंट](/docs/ai/infrastructure-ai-agents#vmware-vcenter)।",
  "**Upgrade** — run the install commands again, then restart the agent. They download the collector release this OneUptime pins with the latest `otel-collector-config.yaml` and systemd unit, and replace the installed ones; your `.env` stays, and a change you made to the config has to be made again:":
    "**अपग्रेड** — इंस्टॉल कमांड फिर से चलाएँ, फिर एजेंट को रीस्टार्ट करें। ये वह कलेक्टर रिलीज़ डाउनलोड करते हैं जिसे यह OneUptime पिन करता है, नवीनतम `otel-collector-config.yaml` और systemd यूनिट के साथ, और इंस्टॉल की हुई फ़ाइलों को बदल देते हैं; आपकी `.env` बनी रहती है, और कॉन्फ़िग में किया गया बदलाव फिर से करना होगा:",
  "Then remove the `oneuptime` user's permission in vCenter if you no longer need it.":
    "फिर, अगर अब ज़रूरत न हो, तो vCenter में `oneuptime` उपयोगकर्ता की अनुमति हटा दें।",
  "The diagnostic script, `troubleshoot.sh`, needs Docker. Without it, start from the service and its log:":
    "जाँच स्क्रिप्ट `troubleshoot.sh` को Docker चाहिए। उसके बिना, सर्विस और उसके लॉग से शुरू करें:",
  "`active (running)`, with `Everything is ready. Begin running and processing data.` in the log, means the collector started; the topics below say what the log means when it cannot reach vCenter or OneUptime. A service that keeps restarting (`activating (auto-restart)`) logs why: `Failed with result 'resources'` means systemd cannot read `/opt/oneuptime-vmware-agent/.env`, and `cannot unmarshal the configuration` or `requires positive value` means a value in it is not one the collector takes — `VCENTER_INSECURE_SKIP_VERIFY` is `true` or `false`, `VCENTER_COLLECTION_INTERVAL` a duration such as `2m`.":
    "लॉग में `Everything is ready. Begin running and processing data.` के साथ `active (running)` का मतलब है कि कलेक्टर शुरू हो गया; नीचे के विषय बताते हैं कि जब वह vCenter या OneUptime तक नहीं पहुँच पाता तो लॉग का क्या मतलब है। बार-बार रीस्टार्ट होने वाली सर्विस (`activating (auto-restart)`) कारण लॉग करती है: `Failed with result 'resources'` का मतलब है कि systemd `/opt/oneuptime-vmware-agent/.env` नहीं पढ़ पाता, और `cannot unmarshal the configuration` या `requires positive value` का मतलब है कि उसमें कोई मान ऐसा है जिसे कलेक्टर स्वीकार नहीं करता — `VCENTER_INSECURE_SKIP_VERIFY` `true` या `false` होता है, `VCENTER_COLLECTION_INTERVAL` `2m` जैसी अवधि।",
  "1. Check that the agent is running: `systemctl status oneuptime-vmware-agent --no-pager`":
    "1. जाँचें कि एजेंट चल रहा है: `systemctl status oneuptime-vmware-agent --no-pager`",
  "2. Check its log for errors: `sudo journalctl -u oneuptime-vmware-agent | grep -i error`":
    "2. इसके लॉग में त्रुटियाँ जाँचें: `sudo journalctl -u oneuptime-vmware-agent | grep -i error`",
  '3. Ask OneUptime whether it takes your ingestion key. `"valid":true` with `"keyType":"Server"` means it does; anything else says what is wrong with the key:':
    '3. OneUptime से पूछें कि क्या वह आपकी इंजेशन कुंजी स्वीकार करता है। `"keyType":"Server"` के साथ `"valid":true` का मतलब हाँ है; कोई और जवाब बताता है कि कुंजी में क्या ग़लत है:',
  "1. Check the log (`sudo journalctl -u oneuptime-vmware-agent -n 100 --no-pager`): a login error (`incorrect user name or password`, `InvalidLogin`) means bad credentials — or a user name or password that is not double-quoted, backslashes doubled, in `.env`; `x509: certificate signed by unknown authority` means TLS verification is on against a certificate this machine does not trust (see **x509 or other TLS errors**); `connection refused` / `no such host` means a wrong `VCENTER_ENDPOINT`; `Exporting failed` with a `401` or `422` means OneUptime refuses the ingestion key.":
    "1. लॉग जाँचें (`sudo journalctl -u oneuptime-vmware-agent -n 100 --no-pager`): लॉगिन त्रुटि (`incorrect user name or password`, `InvalidLogin`) का मतलब है ग़लत क्रेडेंशियल — या ऐसा उपयोगकर्ता नाम या पासवर्ड जो `.env` में दोहरे उद्धरण चिह्नों में, बैकस्लैश दोगुने करके, नहीं लिखा है; `x509: certificate signed by unknown authority` का मतलब है कि ऐसे प्रमाणपत्र के सामने TLS सत्यापन चालू है जिस पर यह मशीन भरोसा नहीं करती (**x509 या अन्य TLS त्रुटियाँ** देखें); `connection refused` / `no such host` का मतलब है ग़लत `VCENTER_ENDPOINT`; `401` या `422` के साथ `Exporting failed` का मतलब है कि OneUptime इंजेशन कुंजी अस्वीकार करता है।",
  "2. Verify the endpoint is reachable. The collector runs on this machine, not in a container, so a plain `curl` takes its path — you should see an XML document advertising `urn:vim25`:":
    "2. पुष्टि करें कि एंडपॉइंट तक पहुँचा जा सकता है। कलेक्टर इसी मशीन पर चलता है, किसी कंटेनर में नहीं, इसलिए एक साधारण `curl` उसी रास्ते से जाता है — आपको `urn:vim25` बताने वाला एक XML दस्तावेज़ दिखना चाहिए:",
  "3. Read the collector's own counters: `otelcol_receiver_accepted_metric_points` grows while vCenter answers, `otelcol_exporter_sent_metric_points` while OneUptime takes the data, and `otelcol_exporter_send_failed_metric_points` appears when it does not:":
    "3. कलेक्टर के अपने काउंटर पढ़ें: `otelcol_receiver_accepted_metric_points` तब तक बढ़ता है जब तक vCenter जवाब देता है, `otelcol_exporter_sent_metric_points` तब तक जब तक OneUptime डेटा लेता है, और जब नहीं लेता तो `otelcol_exporter_send_failed_metric_points` दिखता है:",
  "4. Make sure `VMWARE_VCENTER_NAME` is set — discovery keys on the `vmware.vcenter.name` resource attribute.":
    "4. पक्का करें कि `VMWARE_VCENTER_NAME` सेट है — पहचान `vmware.vcenter.name` रिसोर्स एट्रिब्यूट पर टिकी है।",
  "5. Give it one collection interval: nothing is sent until the first full inventory walk completes.":
    "5. इसे एक संग्रह अंतराल दें: पहली पूरी इन्वेंटरी यात्रा पूरी होने तक कुछ नहीं भेजा जाता।",
  'Use the full principal — `oneuptime@vsphere.local`, or `DOMAIN\\user` / `user@domain.example` for an Active Directory identity source — and check how it and the password are written in `/opt/oneuptime-vmware-agent/.env`. systemd reads that file with rules of its own, and not the same ones in every version: outside quotes it drops a backslash (`DOMAIN\\user` becomes `DOMAINuser`) and nothing starts a comment, and older versions (RHEL 8\'s, for one) drop a backslash inside single quotes too. The form every version reads as typed is double quotes, with each `\\` written `\\\\` and each `"` written `\\"` — `VCENTER_USERNAME="DOMAIN\\\\user"`, `VCENTER_PASSWORD="p@ss$word"`; `$`, `#`, `\'` and spaces go in as they are. Restart the agent after changing either. A locked account (too many failed attempts) rejects a correct password too; check *Administration → Single Sign On → Users and Groups*.':
    'पूरा प्रिंसिपल इस्तेमाल करें — `oneuptime@vsphere.local`, या Active Directory पहचान स्रोत के लिए `DOMAIN\\user` / `user@domain.example` — और जाँचें कि `/opt/oneuptime-vmware-agent/.env` में वह और पासवर्ड कैसे लिखे हैं। systemd उस फ़ाइल को अपने नियमों से पढ़ता है, और हर संस्करण में वे एक जैसे नहीं: उद्धरण चिह्नों के बाहर वह बैकस्लैश हटा देता है (`DOMAIN\\user` बन जाता है `DOMAINuser`) और कोई चीज़ टिप्पणी शुरू नहीं करती, और पुराने संस्करण (जैसे RHEL 8 वाला) एकल उद्धरण चिह्नों के अंदर भी बैकस्लैश हटा देते हैं। जिस रूप को हर संस्करण टाइप किए अनुसार पढ़ता है वह है दोहरे उद्धरण चिह्न, हर `\\` को `\\\\` और हर `"` को `\\"` लिखकर — `VCENTER_USERNAME="DOMAIN\\\\user"`, `VCENTER_PASSWORD="p@ss$word"`; `$`, `#`, `\'` और स्पेस वैसे ही जाते हैं। दोनों में से कोई भी बदलने के बाद एजेंट को रीस्टार्ट करें। लॉक हुआ खाता (बहुत ज़्यादा असफल प्रयास) सही पासवर्ड भी अस्वीकार करता है; *Administration → Single Sign On → Users and Groups* जाँचें।',
  "vCenter appliances present a certificate issued by their own VMCA, which this machine does not trust out of the box. Either set `VCENTER_INSECURE_SKIP_VERIFY=true` (the pragmatic choice on a private management network), or keep verification on: the collector runs on this machine and trusts its CA store, so add vCenter's root certificate to it — the `.0` files under `certs/lin/` in `https://<vcenter>/certs/download.zip`, copied with a `.crt` name into `/usr/local/share/ca-certificates/` and loaded with `sudo update-ca-certificates` on Debian and Ubuntu, or copied into `/etc/pki/ca-trust/source/anchors/` and loaded with `sudo update-ca-trust` on RHEL and its relatives. Restart the agent either way. Do **not** point the endpoint at an `http://` URL — vCenter only serves the SDK over HTTPS.":
    "vCenter उपकरण अपने ही VMCA से जारी प्रमाणपत्र दिखाते हैं, जिस पर यह मशीन अपने-आप भरोसा नहीं करती। या तो `VCENTER_INSECURE_SKIP_VERIFY=true` सेट करें (निजी प्रबंधन नेटवर्क पर यह व्यावहारिक विकल्प है) या सत्यापन चालू रखें: कलेक्टर इसी मशीन पर चलता है और उसके CA स्टोर पर भरोसा करता है, इसलिए vCenter का रूट प्रमाणपत्र उसमें जोड़ें — `https://<vcenter>/certs/download.zip` में `certs/lin/` के नीचे की `.0` फ़ाइलें, Debian और Ubuntu पर `.crt` नाम से `/usr/local/share/ca-certificates/` में कॉपी करके और `sudo update-ca-certificates` से लोड करके, या RHEL और उससे जुड़े सिस्टम पर `/etc/pki/ca-trust/source/anchors/` में कॉपी करके और `sudo update-ca-trust` से लोड करके। दोनों ही स्थितियों में एजेंट को रीस्टार्ट करें। एंडपॉइंट को `http://` URL पर **न** रखें — vCenter SDK केवल HTTPS पर देता है।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. Fix it in `/opt/oneuptime-vmware-agent/.env` and apply it with `sudo systemctl restart oneuptime-vmware-agent` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। इसे `/opt/oneuptime-vmware-agent/.env` में ठीक करें और `sudo systemctl restart oneuptime-vmware-agent` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
  "The vCenter identity comes from `VMWARE_VCENTER_NAME`, stamped on every metric as `vmware.vcenter.name`. This vCenter is **`vcenter-1`**. Fix it in `/opt/oneuptime-vmware-agent/.env` and apply it with `sudo systemctl restart oneuptime-vmware-agent` — note that a new name registers a new vCenter.":
    "vCenter की पहचान `VMWARE_VCENTER_NAME` से आती है, जो हर मेट्रिक पर `vmware.vcenter.name` के रूप में लगती है। यह vCenter **`vcenter-1`** है। इसे `/opt/oneuptime-vmware-agent/.env` में ठीक करें और `sudo systemctl restart oneuptime-vmware-agent` से लागू करें — ध्यान दें कि नया नाम एक नया vCenter दर्ज करता है।",
};

export default TRANSLATION;
